class Icon { constructor(public name: string, public color: string) {} }
class IconFactory {
  private pool = new Map<string, Icon>();
  getIcon(name: string) {
    if (!this.pool.has(name)) this.pool.set(name, new Icon(name, 'black'));
    return this.pool.get(name)!;
  }
}
const factory = new IconFactory();
const iconA = factory.getIcon('save');
iconA.color = 'red';
const iconB = factory.getIcon('save');
// iconB.color is now 'red'

